// Behaviour test for _Rb_tree<CCharString, pair<const CCharString, long>>::_M_copy (retail 0x00432BAB, clone inlined): a
// structural copy of a subtree -- same shape, same colours and values, parent links pointing into the copy, the top
// node's parent set to the given parent.
struct Node { bool color; Node* parent; Node* left; Node* right; const char* key; long value; };
static int g_clones = 0;
static Node* CloneNode(Node* x)
{
    Node* n = (Node*)std::malloc(sizeof(Node));
    n->key = x->key; n->value = x->value; n->color = x->color; n->left = 0; n->right = 0; n->parent = 0;
    ++g_clones;
    return n;
}
static Node* Copy(Node* x, Node* p)
{
    Node* top = CloneNode(x);
    top->parent = p;
    if (x->right)
        top->right = Copy(x->right, top);
    p = top;
    x = x->left;
    while (x != 0) {
        Node* y = CloneNode(x);
        p->left = y;
        y->parent = p;
        if (x->right)
            y->right = Copy(x->right, y);
        p = y;
        x = x->left;
    }
    return top;
}
static Node g_n[7];
static int Same(const Node* a, const Node* b, const Node* parentOfB)
{
    if (!a || !b) return a == b;
    if (a->key != b->key || a->value != b->value || a->color != b->color || b->parent != parentOfB || a == b) return 0;
    return Same(a->left, b->left, b) && Same(a->right, b->right, b);
